# Model of an idempotent "module": check current state, act only if it differs.
state = {"packages": set(), "files": {}}

def package(name):
    if name in state["packages"]:
        return "ok"
    state["packages"].add(name)
    return "changed"

def file_content(path, text):
    if state["files"].get(path) == text:
        return "ok"
    state["files"][path] = text
    return "changed"

def run_play(label):
    results = [package("nginx"), package("git"),
               file_content("/etc/app.conf", "port=80")]
    print(label, results, "changed =", results.count("changed"))

print("start state:", state)
run_play("run 1:")
run_play("run 2:")   # a healthy playbook reports changed = 0 here
# Cost: O(tasks) per run, O(1) extra space per task.

# Host patterns as set algebra: web:&prod:!canary
inventory = {
    "web":    {"web1", "web2", "web3", "web4"},
    "db":     {"db1", "db2"},
    "prod":   {"web1", "web2", "web3", "db1"},
    "canary": {"web1"},
}

def match(pattern):
    result = None
    for part in pattern.split(":"):   # read left to right
        if part.startswith("&"):
            result = result & inventory[part[1:]]
        elif part.startswith("!"):
            result = result - inventory[part[1:]]
        elif result is None:
            result = set(inventory[part])
        else:
            result = result | inventory[part]   # plain name = union
    return sorted(result)

for p in ["web:db", "web:&prod", "web:!canary", "web:&prod:!canary"]:
    print(p.ljust(20), match(p))
print("empty match:", match("db:&canary"))   # just an empty list, not an error

# Why a run passes once and fails twice: shell-style vs module-style.
dirs = set()

def shell_mkdir(path):            # like: shell: mkdir /data
    if path in dirs:
        raise RuntimeError("mkdir: cannot create directory: File exists")
    dirs.add(path)
    return "changed"

def file_directory(path):         # like: file: state=directory
    if path in dirs:
        return "ok"
    dirs.add(path)
    return "changed"

for name, fn in [("shell mkdir", shell_mkdir), ("file module", file_directory)]:
    dirs.clear()
    for n in (1, 2):
        try:
            print(name, "run", n, "->", fn("/data"))
        except RuntimeError as e:
            print(name, "run", n, "-> FAILED:", e)
